# Minimal pure-python SSH2 test client for probing server behaviour
import socket, struct, os, hashlib, hmac, time, sys

P = 2**255 - 19
def x25519(k, u):
    k = bytearray(k); k[0] &= 248; k[31] &= 127; k[31] |= 64
    k = int.from_bytes(k, 'little')
    u = int.from_bytes(u, 'little') & ((1<<255)-1)
    x1 = u; x2 = 1; z2 = 0; x3 = u; z3 = 1; swap = 0
    for t in reversed(range(255)):
        kt = (k >> t) & 1
        swap ^= kt
        if swap: x2, x3 = x3, x2; z2, z3 = z3, z2
        swap = kt
        A = (x2 + z2) % P; AA = A*A % P; B = (x2 - z2) % P; BB = B*B % P
        E = (AA - BB) % P; C = (x3 + z3) % P; D = (x3 - z3) % P
        DA = D*A % P; CB = C*B % P
        x3 = pow(DA + CB, 2, P); z3 = x1 * pow(DA - CB, 2, P) % P
        x2 = AA * BB % P; z2 = E * (AA + 121665 * E) % P
    if swap: x2, x3 = x3, x2; z2, z3 = z3, z2
    return (x2 * pow(z2, P-2, P) % P).to_bytes(32, 'little')

def rotl(v, c): return ((v << c) & 0xffffffff) | (v >> (32 - c))
def chacha20_block(key, counter, nonce8):
    s = [0x61707865, 0x3320646e, 0x79622d32, 0x6b206574] + list(struct.unpack('<8I', key)) + [counter & 0xffffffff, (counter >> 32) & 0xffffffff] + list(struct.unpack('<2I', nonce8))
    x = s[:]
    def qr(a,b,c,d):
        x[a] = (x[a]+x[b]) & 0xffffffff; x[d] = rotl(x[d]^x[a], 16)
        x[c] = (x[c]+x[d]) & 0xffffffff; x[b] = rotl(x[b]^x[c], 12)
        x[a] = (x[a]+x[b]) & 0xffffffff; x[d] = rotl(x[d]^x[a], 8)
        x[c] = (x[c]+x[d]) & 0xffffffff; x[b] = rotl(x[b]^x[c], 7)
    for _ in range(10):
        qr(0,4,8,12); qr(1,5,9,13); qr(2,6,10,14); qr(3,7,11,15)
        qr(0,5,10,15); qr(1,6,11,12); qr(2,7,8,13); qr(3,4,9,14)
    return struct.pack('<16I', *[(x[i]+s[i]) & 0xffffffff for i in range(16)])
def chacha20_xor(key, counter, nonce8, data):
    out = bytearray()
    i = 0
    while i < len(data):
        blk = chacha20_block(key, counter, nonce8); counter += 1
        chunk = data[i:i+64]
        out += bytes(a ^ b for a, b in zip(chunk, blk))
        i += 64
    return bytes(out)
def poly1305(key, msg):
    r = int.from_bytes(key[:16], 'little') & 0x0ffffffc0ffffffc0ffffffc0fffffff
    s = int.from_bytes(key[16:], 'little')
    p = (1 << 130) - 5
    acc = 0
    for i in range(0, len(msg), 16):
        blk = msg[i:i+16]
        n = int.from_bytes(blk + b'\x01', 'little')
        acc = (acc + n) * r % p
    return ((acc + s) & ((1 << 128) - 1)).to_bytes(16, 'little')

def sstr(b): return struct.pack(">I", len(b)) + b
def su32(n): return struct.pack(">I", n)
def sbool(b): return b"\x01" if b else b"\x00"
def smpint(n):
    if n == 0: return sstr(b"")
    b = n.to_bytes((n.bit_length()+8)//8, 'big')
    while len(b) > 1 and b[0] == 0 and not (b[1] & 0x80): b = b[1:]
    return sstr(b)
def namelist(l): return sstr(",".join(l).encode())

class Reader:
    def __init__(self, data): self.d = data; self.o = 0
    def byte(self): v = self.d[self.o]; self.o += 1; return v
    def u32(self): (v,) = struct.unpack(">I", self.d[self.o:self.o+4]); self.o += 4; return v
    def boolean(self): return self.byte() != 0
    def string(self): n = self.u32(); v = self.d[self.o:self.o+n]; self.o += n; return v
    def rest(self): return self.d[self.o:]

MSG = dict(DISCONNECT=1, IGNORE=2, UNIMPLEMENTED=3, DEBUG=4, SERVICE_REQUEST=5, SERVICE_ACCEPT=6, EXT_INFO=7,
    KEXINIT=20, NEWKEYS=21, KEXDH_INIT=30, KEXDH_REPLY=31,
    USERAUTH_REQUEST=50, USERAUTH_FAILURE=51, USERAUTH_SUCCESS=52, USERAUTH_BANNER=53, USERAUTH_PK_OK=60,
    GLOBAL_REQUEST=80, REQUEST_SUCCESS=81, REQUEST_FAILURE=82,
    CHANNEL_OPEN=90, CHANNEL_OPEN_CONFIRMATION=91, CHANNEL_OPEN_FAILURE=92, CHANNEL_WINDOW_ADJUST=93,
    CHANNEL_DATA=94, CHANNEL_EXTENDED_DATA=95, CHANNEL_EOF=96, CHANNEL_CLOSE=97, CHANNEL_REQUEST=98,
    CHANNEL_SUCCESS=99, CHANNEL_FAILURE=100)
MSGNAME = {v: k for k, v in MSG.items()}

class SSHClient:
    def __init__(self, host="127.0.0.1", port=2222, ident=b"SSH-2.0-pytest", timeout=5, verbose=True):
        self.sock = socket.create_connection((host, port))
        self.sock.settimeout(timeout)
        self.ident = ident
        self.verbose = verbose
        self.rbuf = b""
        self.seq_out = 0; self.seq_in = 0
        self.enc = None  # (k_main, k_len) for outgoing
        self.dec = None
        self.session_id = None
        self.kex_strict = False
        self.log = []
    def logv(self, *a):
        if self.verbose: print(*a, file=sys.stderr)
    # --- raw io
    def recv_exact(self, n):
        while len(self.rbuf) < n:
            d = self.sock.recv(65536)
            if not d: raise EOFError("connection closed (have %d want %d)" % (len(self.rbuf), n))
            self.rbuf += d
        v = self.rbuf[:n]; self.rbuf = self.rbuf[n:]; return v
    def read_line(self):
        while b"\n" not in self.rbuf:
            d = self.sock.recv(65536)
            if not d: raise EOFError("closed in ident")
            self.rbuf += d
        i = self.rbuf.index(b"\n"); line = self.rbuf[:i]; self.rbuf = self.rbuf[i+1:]
        return line.rstrip(b"\r")
    def do_version(self, send_first=True):
        if send_first: self.sock.sendall(self.ident + b"\r\n")
        while True:
            line = self.read_line()
            if line.startswith(b"SSH-"): break
            self.logv("pre-ident line:", line)
        self.server_ident = line
        self.logv("server ident:", line)
        if not send_first: self.sock.sendall(self.ident + b"\r\n")
        return line
    def send_packet(self, payload, padlen=None):
        if self.enc is None:
            bs = 8
            if padlen is None:
                padlen = bs - ((len(payload) + 5) % bs)
                if padlen < 4: padlen += bs
            pkt = su32(len(payload) + padlen + 1) + bytes([padlen]) + payload + os.urandom(padlen)
            self.sock.sendall(pkt)
        else:
            k_main, k_len = self.enc
            bs = 8
            if padlen is None:
                padlen = bs - ((len(payload) + 1) % bs)
                if padlen < 4: padlen += bs
            plain = bytes([padlen]) + payload + os.urandom(padlen)
            nonce = struct.pack(">Q", self.seq_out)
            enclen = chacha20_xor(k_len, 0, nonce, su32(len(plain)))
            polykey = chacha20_block(k_main, 0, nonce)[:32]
            encpl = chacha20_xor(k_main, 1, nonce, plain)
            tag = poly1305(polykey, enclen + encpl)
            self.sock.sendall(enclen + encpl + tag)
        self.seq_out = (self.seq_out + 1) & 0xffffffff
    def recv_packet(self):
        if self.dec is None:
            head = self.recv_exact(4)
            (plen,) = struct.unpack(">I", head)
            if plen > 35000: raise ValueError("bad plen %d" % plen)
            body = self.recv_exact(plen)
            padlen = body[0]
            payload = body[1:plen-padlen]
        else:
            k_main, k_len = self.dec
            nonce = struct.pack(">Q", self.seq_in)
            enclen = self.recv_exact(4)
            (plen,) = struct.unpack(">I", chacha20_xor(k_len, 0, nonce, enclen))
            if plen > 35000: raise ValueError("bad plen %d" % plen)
            encpl = self.recv_exact(plen)
            tag = self.recv_exact(16)
            polykey = chacha20_block(k_main, 0, nonce)[:32]
            if poly1305(polykey, enclen + encpl) != tag: raise ValueError("bad mac")
            body = chacha20_xor(k_main, 1, nonce, encpl)
            padlen = body[0]
            payload = body[1:plen-padlen]
        self.seq_in = (self.seq_in + 1) & 0xffffffff
        return payload
    def recv_msg(self, skip_ignore=True):
        while True:
            p = self.recv_packet()
            t = p[0]
            self.logv("<- %s(%d) len=%d" % (MSGNAME.get(t, "?"), t, len(p)))
            if t == MSG["DISCONNECT"]:
                r = Reader(p[1:]); code = r.u32(); desc = r.string()
                self.logv("   DISCONNECT code=%d desc=%r" % (code, desc))
                self.last_disconnect = (code, desc)
                raise EOFError("DISCONNECT %d %r" % (code, desc))
            if skip_ignore and t in (MSG["IGNORE"], MSG["DEBUG"]):
                continue
            return t, p
    def send_msg(self, t, body=b"", **kw):
        self.logv("-> %s(%d) len=%d" % (MSGNAME.get(t, "?"), t, len(body)+1))
        self.send_packet(bytes([t]) + body, **kw)
    # --- kex
    def build_kexinit(self, kex=None, hostkeys=None, ciphers=None, macs=None, comp=None, first_follows=False, cookie=None):
        kex = kex or ["curve25519-sha256", "kex-strict-c-v00@openssh.com"]
        hostkeys = hostkeys or ["ssh-ed25519", "ecdsa-sha2-nistp256", "rsa-sha2-256"]
        ciphers = ciphers or ["chacha20-poly1305@openssh.com"]
        macs = macs or ["hmac-sha2-256"]
        comp = comp or ["none"]
        cookie = cookie if cookie is not None else os.urandom(16)
        return (bytes([MSG["KEXINIT"]]) + cookie + namelist(kex) + namelist(hostkeys) + namelist(ciphers) + namelist(ciphers)
                + namelist(macs) + namelist(macs) + namelist(comp) + namelist(comp) + namelist([]) + namelist([]) + sbool(first_follows) + su32(0))
    def parse_kexinit(self, p):
        r = Reader(p[1:]); cookie = r.d[r.o:r.o+16]; r.o += 16
        names = ["kex", "hostkey", "enc_cs", "enc_sc", "mac_cs", "mac_sc", "comp_cs", "comp_sc", "lang_cs", "lang_sc"]
        d = {n: r.string().decode().split(",") for n in names}
        d["first_follows"] = r.boolean(); d["reserved"] = r.u32(); d["cookie"] = cookie
        return d
    def do_kex(self, my_kexinit=None, verbose_kexinit=False, send_kexinit_first=True):
        if my_kexinit is None: my_kexinit = self.build_kexinit()
        if send_kexinit_first:
            self.send_packet(my_kexinit)
        t, p = self.recv_msg()
        assert t == MSG["KEXINIT"], t
        self.server_kexinit = p
        self.server_kex = self.parse_kexinit(p)
        if verbose_kexinit: self.logv(self.server_kex)
        if not send_kexinit_first:
            self.send_packet(my_kexinit)
        self.kex_strict = "kex-strict-s-v00@openssh.com" in self.server_kex["kex"]
        # curve25519
        priv = os.urandom(32)
        pub = x25519(priv, (9).to_bytes(32, 'little'))
        self.send_msg(MSG["KEXDH_INIT"], sstr(pub))
        t, p = self.recv_msg()
        assert t == MSG["KEXDH_REPLY"], t
        r = Reader(p[1:]); K_S = r.string(); Q_S = r.string(); sig = r.string()
        self.hostkey_blob = K_S; self.hostkey_sig = sig
        shared = x25519(priv, Q_S)
        K = int.from_bytes(shared, 'big')
        h = hashlib.sha256()
        for part in (sstr(self.ident), sstr(self.server_ident), sstr(my_kexinit), sstr(self.server_kexinit), sstr(K_S), sstr(pub), sstr(Q_S), smpint(K)):
            h.update(part)
        H = h.digest()
        if self.session_id is None: self.session_id = H
        self.H = H; self.K = K
        t, p = self.recv_msg()
        assert t == MSG["NEWKEYS"], t
        self.send_msg(MSG["NEWKEYS"])
        def derive(letter, n):
            out = hashlib.sha256(smpint(K) + H + letter + self.session_id).digest()
            while len(out) < n:
                out += hashlib.sha256(smpint(K) + H + out).digest()
            return out[:n]
        kc = derive(b"C", 64); ks = derive(b"D", 64)
        self.enc = (kc[:32], kc[32:])
        self.dec = (ks[:32], ks[32:])
        if self.kex_strict:
            self.seq_out = 0; self.seq_in = 0
        return self.server_kex
    def connect(self, **kw):
        self.do_version()
        return self.do_kex(**kw)
    # --- auth
    def service_request(self, name=b"ssh-userauth"):
        self.send_msg(MSG["SERVICE_REQUEST"], sstr(name))
        t, p = self.recv_msg()
        return t, p
    def userauth_none(self, user=b"agent"):
        self.send_msg(MSG["USERAUTH_REQUEST"], sstr(user) + sstr(b"ssh-connection") + sstr(b"none"))
        return self.recv_auth_response()
    def userauth_password(self, user, password):
        self.send_msg(MSG["USERAUTH_REQUEST"], sstr(user) + sstr(b"ssh-connection") + sstr(b"password") + sbool(False) + sstr(password))
        return self.recv_auth_response()
    def recv_auth_response(self):
        while True:
            t, p = self.recv_msg()
            if t == MSG["USERAUTH_BANNER"]:
                r = Reader(p[1:]); self.logv("   BANNER %r" % r.string()); continue
            if t == MSG["USERAUTH_FAILURE"]:
                r = Reader(p[1:]); methods = r.string(); partial = r.boolean()
                self.logv("   FAILURE methods=%s partial=%s" % (methods, partial))
                return t, (methods, partial)
            if t == MSG["USERAUTH_SUCCESS"]:
                return t, None
            if t == MSG["USERAUTH_PK_OK"]:
                r = Reader(p[1:]); alg = r.string(); blob = r.string()
                return t, (alg, blob)
            return t, p
    def agent_sign(self, keyblob, data):
        a = socket.socket(socket.AF_UNIX); a.connect(os.environ["SSH_AUTH_SOCK"])
        req = bytes([13]) + sstr(keyblob) + sstr(data) + su32(0)
        a.sendall(sstr(req))
        hdr = a.recv(4); (n,) = struct.unpack(">I", hdr); resp = b""
        while len(resp) < n: resp += a.recv(n - len(resp))
        a.close()
        assert resp[0] == 14, resp[0]
        return Reader(resp[1:]).string()
    def userauth_pubkey(self, user, algo, keyblob, sign=True, bad_sig=False):
        if not sign:
            self.send_msg(MSG["USERAUTH_REQUEST"], sstr(user) + sstr(b"ssh-connection") + sstr(b"publickey") + sbool(False) + sstr(algo) + sstr(keyblob))
            return self.recv_auth_response()
        body = sstr(user) + sstr(b"ssh-connection") + sstr(b"publickey") + sbool(True) + sstr(algo) + sstr(keyblob)
        sig = self.agent_sign(keyblob, sstr(self.session_id) + bytes([MSG["USERAUTH_REQUEST"]]) + body)
        if bad_sig: sig = sig[:-1] + bytes([sig[-1] ^ 1])
        self.send_msg(MSG["USERAUTH_REQUEST"], body + sstr(sig))
        return self.recv_auth_response()
    # --- channels
    def channel_open(self, ctype=b"session", window=2**21, maxpkt=32768, extra=b"", chan=0):
        self.send_msg(MSG["CHANNEL_OPEN"], sstr(ctype) + su32(chan) + su32(window) + su32(maxpkt) + extra)
        t, p = self.recv_msg()
        if t == MSG["CHANNEL_OPEN_CONFIRMATION"]:
            r = Reader(p[1:]); mine = r.u32(); theirs = r.u32(); win = r.u32(); mp = r.u32()
            self.logv("   OPEN_CONF mine=%d theirs=%d win=%d maxpkt=%d" % (mine, theirs, win, mp))
            return t, (mine, theirs, win, mp)
        if t == MSG["CHANNEL_OPEN_FAILURE"]:
            r = Reader(p[1:]); mine = r.u32(); code = r.u32(); desc = r.string(); lang = r.string()
            self.logv("   OPEN_FAIL mine=%d code=%d desc=%r" % (mine, code, desc))
            return t, (mine, code, desc)
        return t, p
    def channel_request(self, chan, rtype, body=b"", want_reply=True):
        self.send_msg(MSG["CHANNEL_REQUEST"], su32(chan) + sstr(rtype) + sbool(want_reply) + body)
        if want_reply:
            return self.recv_msg()
    def channel_data(self, chan, data):
        self.send_msg(MSG["CHANNEL_DATA"], su32(chan) + sstr(data))
    def global_request(self, rtype, body=b"", want_reply=True):
        self.send_msg(MSG["GLOBAL_REQUEST"], sstr(rtype) + sbool(want_reply) + body)
        if want_reply: return self.recv_msg()
    def drain(self, timeout=1.0):
        """read messages until timeout; return list"""
        out = []
        self.sock.settimeout(timeout)
        try:
            while True:
                t, p = self.recv_msg()
                out.append((t, p))
                if t == MSG["CHANNEL_DATA"]:
                    r = Reader(p[1:]); c = r.u32(); d = r.string(); self.logv("   DATA chan=%d %r" % (c, d[:200]))
                elif t == MSG["CHANNEL_EXTENDED_DATA"]:
                    r = Reader(p[1:]); c = r.u32(); dt = r.u32(); d = r.string(); self.logv("   EXTDATA chan=%d type=%d %r" % (c, dt, d[:200]))
                elif t == MSG["CHANNEL_REQUEST"]:
                    r = Reader(p[1:]); c = r.u32(); rt = r.string(); wr = r.boolean(); self.logv("   CHANREQ chan=%d %r want_reply=%s rest=%r" % (c, rt, wr, r.rest()))
                elif t == MSG["GLOBAL_REQUEST"]:
                    r = Reader(p[1:]); rt = r.string(); wr = r.boolean(); self.logv("   GLOBALREQ %r want_reply=%s rest=%r" % (rt, wr, r.rest()))
                elif t == MSG["CHANNEL_WINDOW_ADJUST"]:
                    r = Reader(p[1:]); c = r.u32(); n = r.u32(); self.logv("   WINADJ chan=%d +%d" % (c, n))
                elif t in (MSG["CHANNEL_EOF"], MSG["CHANNEL_CLOSE"]):
                    r = Reader(p[1:]); c = r.u32(); self.logv("   chan=%d" % c)
                elif t == MSG["EXT_INFO"]:
                    r = Reader(p[1:]); n = r.u32()
                    for i in range(n): self.logv("   EXT %r = %r" % (r.string(), r.string()))
                elif t == MSG["UNIMPLEMENTED"]:
                    r = Reader(p[1:]); self.logv("   UNIMPLEMENTED seq=%d" % r.u32())
                elif t == MSG["CHANNEL_OPEN"]:
                    r = Reader(p[1:]); ct = r.string(); sc = r.u32(); w = r.u32(); mp = r.u32(); self.logv("   CHANOPEN %r sender=%d win=%d maxpkt=%d rest=%r" % (ct, sc, w, mp, r.rest()))
                elif t == MSG["REQUEST_SUCCESS"] or t == MSG["REQUEST_FAILURE"] or t == MSG["CHANNEL_SUCCESS"] or t == MSG["CHANNEL_FAILURE"]:
                    self.logv("   body=%r" % p[1:])
        except socket.timeout:
            pass
        except EOFError as e:
            self.logv("   EOF:", e); out.append(("EOF", str(e)))
        except ConnectionResetError as e:
            self.logv("   RESET"); out.append(("RESET", str(e)))
        return out

def pubkey_blob(path):
    import base64
    parts = open(path).read().split()
